package scan

import (
	"fmt"
	"go/ast"
	"go/token"
	"regexp"
	"strconv"
	"strings"
	"testing"
)

// DEVDESK-772 guard (Q1): a command template of steps.go never receives a name
// from the repository except through shellQuote.
//
// The folder names in a step come from a repository DevDesk does not trust, and a
// step the user copies is read by a shell. The quoting lives in one helper,
// shellQuote (POSIX single quotes, an apostrophe written '\”), and typedDir and
// typedKustomizeDir may wrap it with the "./" that DEVDESK-763 and DEVDESK-768
// need. This test parses steps.go and fails, naming file and line, when a command
// template is filled with anything else.
//
// What it holds:
//
//	Q1  shellQuote is defined in a non-test file of the package;
//	Q2  in steps.go, a fmt.Sprintf whose format holds a command ("run helm ...",
//	    "Run kustomize ..." and the other programs below) takes only string
//	    literals and calls of a protector as arguments, in any function, not only
//	    the *Steps ones; a protector is shellQuote, or a function of the package
//	    whose body calls it (typedDir, typedKustomizeDir);
//	Q3  the same for a "+" concatenation that holds a command literal;
//	Q4  a command template literal ("run helm lint %s") that is not the format of
//	    a Sprintf is refused: nothing says what fills it, so a constant or a
//	    variable cannot hide a template from Q2.
//
// Limits, written because no check is free of them:
//
//   - It matches names, not types: an argument is a protector because of the name
//     of the function called, so a `shellQuote` that returns its input passes.
//     TestAPastedStepRunsNothingElseAndGivesTheFolderAsOneArgument runs the result.
//   - A command is recognised by the phrase "run <program>" in the template; a
//     step worded "Type helm lint ..." or "Use ..." is not seen. The programs are
//     in stepsCommandPrograms: add one when a step starts to name another.
//   - Only steps.go is read: provenance_guard_test.go already refuses a *Steps
//     function anywhere else, and a Steps that is not from one.
//   - A protector is a function that calls shellQuote on some path; whether the
//     path is taken for every name is not checked (the behavior tests do).
//   - A prose step that names a folder without a command ("move the file below
//     %s.", "Fix what helm lint reports in %s.") is out of Q2, and so are
//     strings.Join, strings.NewReplacer, a template package and reflection.
//   - A control character in a name is a text, not a quote: only the behavior
//     test sees that.
//   - Windows PowerShell and cmd read the single quotes otherwise: documented,
//     not guarded.
const stepsCommandPrograms = "helm|kustomize|kubeconform|kubectl|trivy|gitleaks|plumber|git|docker|podman|cosign"

var stepsCommandTemplate = regexp.MustCompile(`(?i)\brun\s+(?:` + stepsCommandPrograms + `)\b`)

const stepsQuoteHelper = "shellQuote"

// stepQuotingViolations returns one line per breach, each starting with file:line.
func stepQuotingViolations(sources []guardSource) []string {
	var out []string
	if !definesFunc(sources, stepsQuoteHelper) {
		out = append(out, "steps.go:1: "+stepsQuoteHelper+" is not defined in a non-test file of the package: "+
			"the folder names of a step have nothing to be quoted by")
	}
	protectors := stepProtectors(sources)
	for _, src := range sources {
		if src.name != "steps.go" {
			continue
		}
		out = append(out, commandTemplateViolations(src, protectors)...)
	}
	return out
}

func definesFunc(sources []guardSource, name string) bool {
	for _, src := range sources {
		for _, d := range src.file.Decls {
			if fd, ok := d.(*ast.FuncDecl); ok && fd.Recv == nil && fd.Name.Name == name {
				return true
			}
		}
	}
	return false
}

// stepProtectors is shellQuote and every function of the package whose body
// calls it.
func stepProtectors(sources []guardSource) map[string]bool {
	protectors := map[string]bool{stepsQuoteHelper: true}
	for _, src := range sources {
		for _, d := range src.file.Decls {
			fd, ok := d.(*ast.FuncDecl)
			if !ok || fd.Recv != nil || fd.Body == nil {
				continue
			}
			ast.Inspect(fd.Body, func(n ast.Node) bool {
				if call, ok := n.(*ast.CallExpr); ok && isIdentCall(call, stepsQuoteHelper) {
					protectors[fd.Name.Name] = true
				}
				return true
			})
		}
	}
	return protectors
}

func isIdentCall(call *ast.CallExpr, name string) bool {
	id, ok := call.Fun.(*ast.Ident)
	return ok && id.Name == name
}

func isSprintf(call *ast.CallExpr) bool {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok || sel.Sel.Name != "Sprintf" {
		return false
	}
	pkg, ok := sel.X.(*ast.Ident)
	return ok && pkg.Name == "fmt"
}

func stringLiteral(e ast.Expr) (string, bool) {
	lit, ok := e.(*ast.BasicLit)
	if !ok || lit.Kind != token.STRING {
		return "", false
	}
	s, err := strconv.Unquote(lit.Value)
	return s, err == nil
}

// isProtected says an argument is safe to put in a command: a literal, or a call
// of a protector.
func isProtected(e ast.Expr, protectors map[string]bool) bool {
	if _, ok := stringLiteral(e); ok {
		return true
	}
	if call, ok := e.(*ast.CallExpr); ok {
		if id, ok := call.Fun.(*ast.Ident); ok && protectors[id.Name] {
			return true
		}
	}
	return false
}

// describeArg is what the message shows of an argument.
func describeArg(src guardSource, e ast.Expr) string {
	p, q := src.fset.Position(e.Pos()), src.fset.Position(e.End())
	if p.Line != q.Line || q.Column <= p.Column {
		return "an expression"
	}
	return fmt.Sprintf("the expression at column %d", p.Column)
}

func commandTemplateViolations(src guardSource, protectors map[string]bool) []string {
	var out []string
	handled := map[*ast.BasicLit]bool{}
	reported := map[token.Pos]bool{}
	report := func(n ast.Node, format string, args ...any) {
		if reported[n.Pos()] {
			return
		}
		reported[n.Pos()] = true
		out = append(out, pos(src, n)+": "+fmt.Sprintf(format, args...))
	}

	ast.Inspect(src.file, func(n ast.Node) bool {
		switch n := n.(type) {
		case *ast.CallExpr:
			if !isSprintf(n) || len(n.Args) == 0 {
				return true
			}
			format, ok := stringLiteral(n.Args[0])
			if !ok {
				return true
			}
			handled[n.Args[0].(*ast.BasicLit)] = true
			if !stepsCommandTemplate.MatchString(format) {
				return true
			}
			for _, arg := range n.Args[1:] {
				if !isProtected(arg, protectors) {
					report(arg, "the command %q is filled with %s that does not go through %s: a folder name from the repository must be quoted",
						format, describeArg(src, arg), stepsQuoteHelper)
				}
			}
		case *ast.BinaryExpr:
			if n.Op != token.ADD {
				return true
			}
			operands := flattenAdd(n)
			command := ""
			for _, op := range operands {
				if s, ok := stringLiteral(op); ok && stepsCommandTemplate.MatchString(s) {
					command = s
					if lit, ok := op.(*ast.BasicLit); ok {
						handled[lit] = true
					}
				}
			}
			if command == "" {
				return true
			}
			for _, op := range operands {
				if !isProtected(op, protectors) {
					report(op, "the command %q is built with + and %s, which does not go through %s",
						command, describeArg(src, op), stepsQuoteHelper)
				}
			}
		}
		return true
	})

	// Q4: a template that is not the format of a Sprintf, or part of a "+".
	ast.Inspect(src.file, func(n ast.Node) bool {
		lit, ok := n.(*ast.BasicLit)
		if !ok || lit.Kind != token.STRING || handled[lit] {
			return true
		}
		if s, ok := stringLiteral(lit); ok && stepsCommandTemplate.MatchString(s) && strings.Contains(s, "%") {
			report(lit, "the command template %q is not the format of a fmt.Sprintf: nothing shows what fills it", s)
		}
		return true
	})
	return out
}

// flattenAdd lists the operands of a chain a + b + c.
func flattenAdd(e ast.Expr) []ast.Expr {
	if b, ok := e.(*ast.BinaryExpr); ok && b.Op == token.ADD {
		return append(flattenAdd(b.X), flattenAdd(b.Y)...)
	}
	return []ast.Expr{e}
}

const quotedStepsSource = `package scan

import (
	"fmt"
	"strings"
)

func shellQuote(s string) string { return "'" + strings.ReplaceAll(s, "'", "'\\''") + "'" }

func typedDir(dir string) string {
	if strings.HasPrefix(dir, "-") {
		return shellQuote("./" + dir)
	}
	return shellQuote(dir)
}

func renderSteps(target string) []string {
	return []string{
		fmt.Sprintf("Run helm template %s and fix the first error it reports.", typedDir(target)),
		fmt.Sprintf("If a dependency is missing, run helm dependency build %s.", shellQuote(target)),
		fmt.Sprintf("Fix what helm lint reports in %s.", target),
		fmt.Sprintf("Render it with %s and validate the output.", target),
	}
}
`

func stepSourcesNamed(t *testing.T, steps string, others ...string) []guardSource {
	t.Helper()
	files := map[string]string{"steps.go": steps}
	for i, o := range others {
		files[fmt.Sprintf("other%d.go", i)] = o
	}
	return parseGuardSources(t, files)
}

// The detector must be able to fail: each breach below is a steps.go that must be
// refused, and the one that follows the rule must pass.
func TestTheQuotingGuardCatchesWhatItIsWrittenFor(t *testing.T) {
	const header = "package scan\n\nimport \"fmt\"\n\nfunc shellQuote(s string) string { return \"'\" + s + \"'\" }\n\n"
	cases := []struct {
		name string
		src  string
		want string
	}{
		{"a bare name", header + `func f(target string) string { return fmt.Sprintf("Run helm template %s now.", target) }`, "does not go through shellQuote"},
		{"a bare name in a lowercase run", header + `func f(dir string) string { return fmt.Sprintf("If it fails, run kustomize build %s.", dir) }`, "does not go through shellQuote"},
		{"a function that does not quote", header + `func typedDir(d string) string { return d }
func f(dir string) string { return fmt.Sprintf("Run helm lint %s.", typedDir(dir)) }`, "does not go through shellQuote"},
		{"a method call", header + `func f(a struct{ Dir string }) string { return fmt.Sprintf("Run helm lint %s.", a.Dir) }`, "does not go through shellQuote"},
		{"a second argument", header + `func f(dir, other string) string { return fmt.Sprintf("Run helm lint %s in %s.", shellQuote(dir), other) }`, "does not go through shellQuote"},
		{"a concatenation", header + `func f(chart string) string { return "Run helm lint " + chart + " again." }`, "built with +"},
		{"a template held in a constant", header + `const tpl = "Run helm template %s."
func f(dir string) string { return fmt.Sprintf(tpl, dir) }`, "not the format of a fmt.Sprintf"},
		{"a function that is not a *Steps function", header + `func describe(dir string) string { return fmt.Sprintf("Run trivy fs %s.", dir) }`, "does not go through shellQuote"},
	}
	for _, c := range cases {
		got := strings.Join(stepQuotingViolations(stepSourcesNamed(t, c.src)), "\n")
		if !strings.Contains(got, c.want) || !strings.Contains(got, "steps.go:") {
			t.Errorf("%s: violations = %q, want one at steps.go:<line> mentioning %q", c.name, got, c.want)
		}
	}

	if got := stepQuotingViolations(stepSourcesNamed(t, "package scan\n")); len(got) != 1 || !strings.Contains(got[0], "shellQuote is not defined") {
		t.Errorf("no helper: violations = %q, want the missing helper", got)
	}
}

func TestTheQuotingGuardAcceptsAQuotedFolderAndProse(t *testing.T) {
	if got := stepQuotingViolations(stepSourcesNamed(t, quotedStepsSource)); len(got) != 0 {
		t.Errorf("a source that quotes was flagged: %q", got)
	}
	// The helper may live in another file of the package.
	steps := `package scan
import "fmt"
func renderSteps(target string) []string {
	return []string{fmt.Sprintf("Run helm template %s.", shellQuote(target))}
}
`
	helper := "package scan\nfunc shellQuote(s string) string { return s }\n"
	if got := stepQuotingViolations(stepSourcesNamed(t, steps, helper)); len(got) != 0 {
		t.Errorf("a helper in another file was not found: %q", got)
	}
	// A violation outside steps.go is none of this guard's business.
	other := "package scan\nimport \"fmt\"\nfunc g(d string) string { return fmt.Sprintf(\"Run helm lint %s.\", d) }\n"
	if got := stepQuotingViolations(stepSourcesNamed(t, quotedStepsSource, other)); len(got) != 0 {
		t.Errorf("a file other than steps.go was read: %q", got)
	}
}

// The real steps.go: red until shellQuote exists and typedDir and typedKustomizeDir
// go through it.
func TestNoStepInterpolatesAFolderNameWithoutShellQuote(t *testing.T) {
	sources := parseGuardSources(t, packageGuardSources(t))
	var seenSteps bool
	for _, s := range sources {
		seenSteps = seenSteps || s.name == "steps.go"
	}
	if !seenSteps {
		t.Fatal("steps.go not found: the guard would pass on nothing")
	}
	for _, v := range stepQuotingViolations(sources) {
		t.Error(v)
	}
}

package scan

import (
	"reflect"
	"strings"
	"testing"
	"unicode"

	"github.com/anthnel/devdesk/internal/testutil/stepshell"
)

// DEVDESK-772: a step that tells the user to type a command is read by a shell,
// and the folder in it comes from a repository DevDesk does not trust. DEVDESK-768
// only put "./" in front of a name that starts with "-". The decision:
//
//   - a name that is not made of plain path characters is wrapped in POSIX single
//     quotes, an apostrophe inside it written '\'' ;
//   - a name no form protects safely (a line break, any control character) makes
//     the step a text on one line saying the folder name needs quoting, not a
//     command to copy;
//   - an ordinary folder keeps its plain name, with no apostrophe;
//   - the limit is documented, not coded: PowerShell and cmd read these quotes
//     differently, and there is no form per platform.
//
// The behavior tests go through the *Steps functions as they are today, so they
// fail on what a user would copy. The helper they expect is shellQuote (the
// guard in steps_quoting_guard_test.go looks for it by name).

// hostileFolder is a folder name that makes a shell run or split something when it
// is pasted bare, with the form the steps must show instead: single-quoted.
type hostileFolder struct {
	name   string
	dir    string
	quoted string
}

// listed by the story
var storyFolders = []hostileFolder{
	{"command substitution", "$(touch pwned)", `'$(touch pwned)'`},
	{"semicolon", "a;touch pwned", `'a;touch pwned'`},
	{"backticks", "`id`", "'`id`'"},
	{"space", "a b", `'a b'`},
	{"apostrophe", "a'b", `'a'\''b'`},
	{"ampersand", "a&b", `'a&b'`},
	{"pipe", "a|b", `'a|b'`},
	{"glob", "a*", `'a*'`},
}

// More ways a bare word is read wrongly. The step must show a quoted form too,
// but only what the shell does with the pasted command is held here.
var moreFolders = []hostileFolder{
	{"redirection", "a>pwned", `'a>pwned'`},
	{"comment", "#c", `'#c'`},
	{"tilde", "~root", `'~root'`},
	{"backslash", `a\b`, `'a\b'`},
	{"double quote", `a"b`, `'a"b'`},
	{"history", "!x", `'!x'`},
	{"brace", "{a,b}", `'{a,b}'`},
	{"parenthesis", "a(b)", `'a(b)'`},
	{"dollar variable", "$HOME", `'$HOME'`},
	{"two spaces", "a  b", `'a  b'`},
}

// A step's command, as the four sentences DevDesk writes today; these are the
// frozen wordings of steps.go.
type commandStep struct {
	program string // what Command looks for
	stubs   string // the program the shell runs
	argv    []string
	steps   func(dir string) []string
	index   int
	text    func(word string) string
}

var commandSteps = []commandStep{
	{
		"helm template", "helm", []string{"template"},
		func(dir string) []string { return renderSteps(SourceHelm, dir, ToolSourceBinary, "boom", false) },
		0, func(w string) string { return "Run helm template " + w + " and fix the first error it reports." },
	},
	{
		"helm dependency build", "helm", []string{"dependency", "build"},
		func(dir string) []string { return renderSteps(SourceHelm, dir, ToolSourceBinary, "boom", false) },
		1, func(w string) string { return "If a dependency is missing, run helm dependency build " + w + "." },
	},
	{
		"helm lint", "helm", []string{"lint"},
		func(dir string) []string { return helmLintSteps(dir+"/templates/a.yaml", dir) },
		1, func(w string) string { return "Run helm lint " + w + " again to confirm." },
	},
	{
		"kustomize build", "kustomize", []string{"build"},
		func(dir string) []string { return renderSteps(SourceKustomize, dir, ToolSourceBinary, "boom", false) },
		0, func(w string) string { return "Run kustomize build " + w + " and fix the first error it reports." },
	},
}

func TestTheStepsShowAHostileFolderNameInSingleQuotes(t *testing.T) {
	for _, f := range append(append([]hostileFolder{}, storyFolders...), moreFolders...) {
		for _, c := range commandSteps {
			t.Run(f.name+"/"+c.program, func(t *testing.T) {
				steps := c.steps(f.dir)
				if c.index >= len(steps) {
					t.Fatalf("steps = %q, want at least %d", steps, c.index+1)
				}
				if got, want := steps[c.index], c.text(f.quoted); got != want {
					t.Errorf("step = %q, want %q", got, want)
				}
			})
		}
	}
}

// What a pasted step does is the whole point: nothing runs but the tool, and the
// tool receives the folder name, whole, as one argument.
func TestAPastedStepRunsNothingElseAndGivesTheFolderAsOneArgument(t *testing.T) {
	stepshell.Available(t)
	for _, f := range append(append([]hostileFolder{}, storyFolders...), moreFolders...) {
		for _, c := range commandSteps {
			t.Run(f.name+"/"+c.program, func(t *testing.T) {
				steps := c.steps(f.dir)
				if c.index >= len(steps) {
					t.Fatalf("steps = %q, want at least %d", steps, c.index+1)
				}
				cmd, ok := stepshell.Command(steps[c.index], c.program)
				if !ok {
					t.Fatalf("step %q holds no %q command", steps[c.index], c.program)
				}
				res := stepshell.Run(t, cmd, c.stubs)
				if res.Pwned {
					t.Errorf("pasting %q created the file pwned: the folder name ran as code", cmd)
				}
				if !res.Called {
					t.Fatalf("pasting %q never reached %s (stderr %q)", cmd, c.stubs, res.Stderr)
				}
				want := append(append([]string{}, c.argv...), f.dir)
				if !reflect.DeepEqual(res.Args, want) {
					t.Errorf("pasting %q gave %s the arguments %q, want %q", cmd, c.stubs, res.Args, want)
				}
			})
		}
	}
}

// What is written for a folder a shell reads as it is stays as it is, and a
// dash still gets its "./": a quote is added only where a shell needs one.
func TestAnOrdinaryFolderKeepsItsPlainNameAndADashGetsOnlyItsDotSlash(t *testing.T) {
	tests := []struct {
		name string
		dir  string
		word string // as helm and kustomize are told to read it
		kust string // kustomize, which also reads a dotted first segment as a remote base
	}{
		{"chart", "charts/app", "charts/app", "charts/app"},
		{"overlay", "kustomizations/dev", "kustomizations/dev", "kustomizations/dev"},
		{"underscore, plus and equal", "charts/a_b+c=d", "charts/a_b+c=d", "charts/a_b+c=d"},
		{"dash", "-x", "./-x", "./-x"},
		{"option-looking", "--load-restrictor=LoadRestrictionsNone", "./--load-restrictor=LoadRestrictionsNone", "./--load-restrictor=LoadRestrictionsNone"},
		{"dash below the first segment", "charts/-x", "charts/-x", "charts/-x"},
		{"dotted host", "github.com/org/repo", "github.com/org/repo", "./github.com/org/repo"},
		{"scp-like", "git@host:o/r", "git@host:o/r", "./git@host:o/r"},
		// Both protections at once: the dot-slash first, then the quotes around the whole.
		{"dash and a command", "-x $(id)", `'./-x $(id)'`, `'./-x $(id)'`},
		{"dash and a quote", "-x'y", `'./-x'\''y'`, `'./-x'\''y'`},
		{"remote-looking and a blank", "github.com/o r", `'github.com/o r'`, `'./github.com/o r'`},
		{"dotted first segment and a pipe", "a.b/c|d", `'a.b/c|d'`, `'./a.b/c|d'`},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			for _, c := range commandSteps {
				word := tt.word
				if c.stubs == "kustomize" {
					word = tt.kust
				}
				steps := c.steps(tt.dir)
				if got, want := steps[c.index], c.text(word); got != want {
					t.Errorf("%s: step = %q, want %q", c.program, got, want)
				}
				if !strings.ContainsAny(tt.dir, " $'|") && strings.Contains(strings.Join(steps, "\n"), "'") {
					t.Errorf("%s: an ordinary folder got an apostrophe: %q", c.program, steps)
				}
			}
		})
	}
}

func TestADashFolderWithAnInjectionIsDotSlashedAndQuotedWhenPasted(t *testing.T) {
	stepshell.Available(t)
	const dir = "-x $(touch pwned)"
	for _, c := range commandSteps {
		t.Run(c.program, func(t *testing.T) {
			cmd, ok := stepshell.Command(c.steps(dir)[c.index], c.program)
			if !ok {
				t.Fatalf("no %q command in %q", c.program, c.steps(dir))
			}
			res := stepshell.Run(t, cmd, c.stubs)
			if res.Pwned {
				t.Errorf("pasting %q created the file pwned", cmd)
			}
			want := append(append([]string{}, c.argv...), "./"+dir)
			if !reflect.DeepEqual(res.Args, want) {
				t.Errorf("pasting %q gave %q, want %q", cmd, res.Args, want)
			}
		})
	}
}

// controlFolders are names no quote protects once pasted: a line break ends the
// command, and a control character is read by the terminal before the shell sees
// it (an escape sequence rewrites the screen, a tab completes). The payload
// "touch pwned" is what a second command would be.
var controlFolders = []struct{ name, dir string }{
	{"line feed", "x\ntouch pwned"},
	{"carriage return", "x\rtouch pwned"},
	{"CRLF", "x\r\ntouch pwned"},
	{"escape sequence", "x\x1b[2Jtouch pwned"},
	{"tab", "x\ttouch pwned"},
	{"delete", "x\x7ftouch pwned"},
	{"next line", "x\u0085touch pwned"},
	{"vertical tab", "x\vtouch pwned"},
	{"bell", "x\atouch pwned"},
	{"line feed after a quote", "a'\ntouch pwned"},
	{"dash and a line feed", "-x\ntouch pwned"},
}

// Every step of every list, whatever the branch: none spans two lines or holds a
// control character, so none can start a second command or move the cursor. The
// steps that are commands are texts then, which say the name needs quoting and do
// not repeat it.
func TestAFolderNameWithALineBreakOrAControlCharacterGivesOneLineAndNoCommand(t *testing.T) {
	for _, f := range controlFolders {
		t.Run(f.name, func(t *testing.T) {
			lists := map[string][]string{
				"helm render":       renderSteps(SourceHelm, f.dir, ToolSourceBinary, "boom", false),
				"kustomize build":   renderSteps(SourceKustomize, f.dir, ToolSourceBinary, "boom", false),
				"kustomize, binary": renderSteps(SourceKustomize, f.dir, ToolSourceBinary, loadRestrictorStderr, false),
				"kustomize, mount":  renderSteps(SourceKustomize, f.dir, ToolSourceContainer, "no such file or directory", false),
				"kustomize blocked": renderSteps(SourceKustomize, f.dir, ToolSourceBinary, sshBlockedStderr, true),
				"helm lint":         helmLintSteps(f.dir+"/templates/a.yaml", f.dir),
				"helm lint, chart":  helmLintSteps(f.dir, f.dir),
			}
			for list, steps := range lists {
				for _, s := range steps {
					if strings.ContainsFunc(s, unicode.IsControl) {
						t.Errorf("%s: step %q holds a line break or a control character", list, s)
					}
				}
				for _, p := range stepProblems(steps) {
					t.Errorf("%s: %s", list, p)
				}
			}

			commands := map[string]string{}
			for _, c := range commandSteps {
				var steps []string
				switch c.program {
				case "helm template", "helm dependency build":
					steps = lists["helm render"]
				case "helm lint":
					steps = lists["helm lint"]
				default:
					steps = lists["kustomize build"]
				}
				if c.index >= len(steps) {
					t.Fatalf("%s: steps = %q, want at least %d", c.program, steps, c.index+1)
				}
				commands[c.program] = steps[c.index]
			}
			for program, step := range commands {
				if !strings.Contains(strings.ToLower(step), "needs quoting") {
					t.Errorf("%s: step %q is not the text saying the folder name needs quoting", program, step)
				}
				if strings.Contains(step, "touch pwned") {
					t.Errorf("%s: step %q repeats the name", program, step)
				}
				if cmd, ok := stepshell.Command(step, program); ok {
					t.Errorf("%s: step %q still holds a command to copy (%q)", program, step, cmd)
				}
			}
		})
	}
}

// localRepro (DEVDESK-772, checked): a Repro is built by reproLine, which refuses a
// token that is not PlainWords, holds a blank or starts with "-". It never quotes,
// so it has no such defect: a hostile name gives no Repro, and a name it accepts
// gives a command a shell reads as it is. This pins that, so a change to
// PlainWords cannot open the same hole without a test failing.
func TestAReproNeverCarriesAFolderNameAShellWouldReadWrongly(t *testing.T) {
	stepshell.Available(t)
	tool := ToolSpec{Source: ToolSourceBinary}
	var names []string
	for _, f := range append(append([]hostileFolder{}, storyFolders...), moreFolders...) {
		names = append(names, f.dir)
	}
	for _, f := range controlFolders {
		names = append(names, f.dir)
	}
	names = append(names, "-x", "-x $(id)", "charts/app", "charts/a_b+c=d", "git@host:o/r", "a=b", "a^b", "a%b", "a^", "^a", "%a", "=a", "a~")
	for _, name := range names {
		repro, _ := renderRepro(tool, "helm", "template", name)
		if repro == "" {
			continue
		}
		res := stepshell.Run(t, repro, "helm")
		want := []string{"template", name}
		if res.Pwned || !reflect.DeepEqual(res.Args, want) {
			t.Errorf("Repro %q for the folder %q: arguments %q (pwned %v), want %q", repro, name, res.Args, res.Pwned, want)
		}
	}
	if repro, _ := renderRepro(tool, "helm", "template", "charts/app"); repro != "helm template charts/app" {
		t.Errorf("Repro for an ordinary folder = %q, want %q", repro, "helm template charts/app")
	}
	for _, name := range []string{"$(touch pwned)", "a b", "a'b", "x\ntouch pwned", "-x"} {
		if repro, _ := renderRepro(tool, "helm", "template", name); repro != "" {
			t.Errorf("Repro for the folder %q = %q, want none", name, repro)
		}
	}
}
// Package stepshell pastes a command a finding's Steps tell the user to copy
// into a real POSIX shell (DEVDESK-772), and reports what the shell did with it.
//
// The folder names in a step come from a repository DevDesk does not trust. A
// step is correct only if a shell reads the folder as one literal argument and
// runs nothing else, and no string comparison proves that: this runs it.
//
// The shell is `sh -c` in a fresh temporary directory, with a stub in place of
// each program the command names. A stub runs nothing: it records the argv it
// received. A name that breaks out of its word shows up as a file `pwned`
// created by the injected `touch pwned`, as a different argv, or as a stub never
// called.
//
// It imports testing and is meant to be imported from _test.go files only, so
// it never reaches the production binary.
package stepshell

import (
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"runtime"
	"strings"
	"testing"
)

// Result is what the shell did with a pasted command.
type Result struct {
	// Called says a stub ran. False means the shell never reached the program:
	// a syntax error, or a word that swallowed the whole command.
	Called bool
	// Args is the argv the stub received, without the program name.
	Args []string
	// Pwned says the file `pwned` exists in the directory the command ran in:
	// something the command was not meant to run created it.
	Pwned bool
	// Stderr is what the shell printed on its error output.
	Stderr string
}

// tails are what a step says after the command it holds, longest first. A command
// ends where its sentence continues, or at the period that closes the step.
var tails = []string{
	" and fix the first error it reports.",
	" again to confirm.",
	".",
}

// Command is the command a step tells the user to copy: the text from program
// (for example "helm template") to the end of the command, without the words
// that continue the sentence. A command is introduced by "run" ("Run helm lint
// ...", "..., run helm dependency build ..."): a sentence that merely names the
// program ("Fix what helm lint reports in ...") holds none. It reports false
// when the step holds no such command. A step that is not a copyable command,
// such as a text saying a folder name needs quoting, must give false for the
// program it would run.
func Command(step, program string) (string, bool) {
	loc := regexp.MustCompile(`(?i)\brun ` + regexp.QuoteMeta(program) + ` `).FindStringIndex(step)
	if loc == nil {
		return "", false
	}
	rest := step[loc[0]+len("run "):]
	for _, tail := range tails {
		if cmd, found := strings.CutSuffix(rest, tail); found {
			return cmd, true
		}
	}
	return rest, true
}

// Available skips the test when no POSIX shell can run the command.
func Available(t testing.TB) {
	t.Helper()
	if runtime.GOOS == "windows" {
		t.Skip("the steps are written for a POSIX shell")
	}
	if _, err := exec.LookPath("sh"); err != nil {
		t.Skip("no sh on PATH")
	}
}

// Run pastes command into `sh -c`, from a fresh temporary directory that holds
// three decoy files (a1, a2 and x) so that an unquoted glob has something to
// expand to, and with a recording stub for each of programs (the first word of
// the command, such as "helm" or "kustomize"). It skips the test when there is
// no shell.
func Run(t testing.TB, command string, programs ...string) Result {
	t.Helper()
	Available(t)

	cwd, stubs, out := t.TempDir(), t.TempDir(), filepath.Join(t.TempDir(), "argv")
	for _, decoy := range []string{"a1", "a2", "x"} {
		if err := os.WriteFile(filepath.Join(cwd, decoy), nil, 0o600); err != nil {
			t.Fatalf("decoy file: %v", err)
		}
	}
	// One argument per NUL-terminated record: no argument can hold a NUL.
	const stub = "#!/bin/sh\nprintf '%s\\0' \"$@\" > \"$STEPSHELL_OUT\"\n"
	for _, program := range programs {
		if err := os.WriteFile(filepath.Join(stubs, program), []byte(stub), 0o700); err != nil {
			t.Fatalf("stub %s: %v", program, err)
		}
	}

	cmd := exec.Command("sh", "-c", command)
	cmd.Dir = cwd
	cmd.Env = []string{
		"PATH=" + stubs + string(os.PathListSeparator) + "/usr/bin:/bin",
		"STEPSHELL_OUT=" + out,
		"HOME=" + cwd,
		"LC_ALL=C",
	}
	stderr := &strings.Builder{}
	cmd.Stderr = stderr
	_ = cmd.Run() // a failure is a Result, not an error: the test reads Called and Stderr

	res := Result{Stderr: stderr.String()}
	if _, err := os.Stat(filepath.Join(cwd, "pwned")); err == nil {
		res.Pwned = true
	}
	if raw, err := os.ReadFile(out); err == nil {
		res.Called = true
		if len(raw) > 0 {
			res.Args = strings.Split(strings.TrimSuffix(string(raw), "\x00"), "\x00")
		}
	}
	return res
}

